select sd.goods_id as goodsId,sd.sell_price as sellPrice,sd.sell_num as sellNum,sd.goods_state as goodsState,sd.supplier_price,sd.goods_info,sd.need_update,sd.up_time, sd.market_id as marketId,sd.id,sp.deliver_time_type as deliverTimeType,sp.max_deliver_day as maxDeliverDay, sp.name as goodsName,sp.img as goodsPicture,sp.title,sd.unit_price as unitPrice,sd.supplier_price as supplierPrice,sd.create_time as createTime, sp.market_price, sp.virtual_sale_num from store_distribution sd inner join spu sp on sd.goods_id = sp.id where sd.data_type = 0
and sd.channel_id = #{query.channelId}
and sd.store_id = #{query.storeId}
${query.sortSQL}

select sd.*,sp.name as goods_name,sp.img as goodsPicture,
sp.virtual_sale_num,
(select GROUP_CONCAT(sku_sd.sku_id)
from store_distribution sku_sd
where sku_sd.goods_id = sd.goods_id
and sku_sd.store_id = sd.store_id
and sku_sd.channel_id = sd.channel_id
and sku_sd.data_type = 1) as skuIds
from store_distribution sd
inner join spu sp on sd.goods_id = sp.id
where sd.data_type = 0

