SELECT sd.*,s.name,s.img,s.virtual_sale_num from store_distribution sd inner join spu s on sd.goods_id = s.id where sd.data_type = 0 and sd.goods_state = 0
and s.category_id like CONCAT(#{query.categoryId},'%')
and s.name like CONCAT('%',#{query.goodsName},'%')
and sd.sell_price between #{query.sellPriceL} and #{query.sellPriceR}
and sd.recommendation_time IS NOT NULL
${query.sortSQL}

SELECT t.* FROM ( SELECT sd.*,s.name,s.img, ROW_NUMBER() OVER (PARTITION BY sd.store_id ORDER BY RAND()) AS rn FROM store_distribution sd inner join spu s on sd.goods_id = s.id WHERE sd.store_id IN
#{storeId}
AND sd.data_type = 0 AND sd.goods_state = 0 ) t WHERE t.rn <= #{limitNum}
